import openpyxl, re
wb=openpyxl.load_workbook('/root/data/workbook.xlsx', data_only=False)
percentile_forms=[]
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            v=cell.value
            if isinstance(v,str) and v.startswith('=') and 'PERCENTILE' in v.upper():
                percentile_forms.append((ws.title, cell.coordinate, v))
print('Found percentile formulas:', percentile_forms)

# also look for functions with .INC style usage
inc_forms=[]
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            v=cell.value
            if isinstance(v,str) and v.startswith('=') and '.INC' in v.upper():
                inc_forms.append((ws.title, cell.coordinate, v))
print('Found .INC formulas:', inc_forms[:20])
